window.VO = [{"text": "One hundred prisoners. One hundred boxes. And one very strange deal.", "cap": "100 prisoners \u00b7 100 boxes", "dur": 4.04, "extra": 0.4, "file": "vo/00.wav"}, {"text": "Each prisoner's number is hidden inside one of the boxes, shuffled at random.", "cap": "Each number hidden in a box", "dur": 4.234, "extra": 0.5, "file": "vo/01.wav"}, {"text": "One at a time, each prisoner may open fifty boxes, looking for their own number.", "cap": "Open up to 50 boxes", "dur": 4.67, "extra": 0.5, "file": "vo/02.wav"}, {"text": "Then every box is closed again. No marks, no signals, no talking.", "cap": "No signals. No talking.", "dur": 4.027, "extra": 0.4, "file": "vo/03.wav"}, {"text": "If every single prisoner finds their number, they all go free. If even one fails, nobody does.", "cap": "All 100 must find it", "dur": 5.474, "extra": 0.6, "file": "vo/04.wav"}, {"text": "Guessing at random, their chance is about one in a million trillion trillion.", "cap": "Random guessing \u2248 0%", "dur": 3.944, "extra": 0.6, "file": "vo/05.wav"}, {"text": "Is there a better plan? Pause, and comment yours!", "cap": "Comment your plan!", "dur": 2.582, "extra": 9.2, "file": "vo/06.wav"}, {"text": "Here's the trick. First, open the box with your own number on the lid.", "cap": "Open YOUR number's box first", "dur": 3.519, "extra": 0.6, "file": "vo/07.wav"}, {"text": "Whatever number is inside, open that box next. And keep following the chain.", "cap": "Follow the chain", "dur": 4.572, "extra": 0.6, "file": "vo/08.wav"}, {"text": "The boxes always form loops, so the chain must lead back to your own number.", "cap": "Every chain loops back to you", "dur": 3.965, "extra": 0.6, "file": "vo/09.wav"}, {"text": "Let's try it with eight boxes, and four tries each.", "cap": "Try it: 8 boxes, 4 tries", "dur": 2.665, "extra": 0.4, "file": "vo/10.wav"}, {"text": "Prisoner three opens box three. Inside is six. Box six holds one. And box one holds three. Found it!", "cap": "3 \u2192 6 \u2192 1 \u2192 3 \u2713", "dur": 6.719, "extra": 0.7, "file": "vo/11.wav"}, {"text": "That loop has three boxes, so everyone on it finds their number in three tries.", "cap": "Loop of 3 = 3 tries", "dur": 4.424, "extra": 0.5, "file": "vo/12.wav"}, {"text": "The plan only fails if some loop is longer than half the boxes.", "cap": "Fails only if a loop is too long", "dur": 3.529, "extra": 0.6, "file": "vo/13.wav"}, {"text": "With a hundred boxes, there's no loop that long about thirty one percent of the time.", "cap": "No long loop \u2248 31% of the time", "dur": 4.352, "extra": 0.6, "file": "vo/14.wav"}, {"text": "So their chance jumps from almost zero, to thirty one percent!", "cap": "\u2248 0% \u2192 31%", "dur": 3.298, "extra": 1.0, "file": "vo/15.wav"}, {"text": "Would you trust the loop? Follow for more puzzles!", "cap": "Follow for more puzzles", "dur": 2.463, "extra": 1.6, "file": "vo/16.wav"}];
